def epsilon_schedule(episode):
    if episode<100: return max(0.1,1.0-0.009*episode)
    return max(0.01,0.1*(0.995**(episode-100)))
def choose_action(state,episode,agent):
    if np.random.random()<epsilon_schedule(episode):return int(np.random.randint(action_size))
    return int(np.argmax(agent(np.asarray(state).reshape(1,-1),training=False).numpy()[0]))
