def run_custom_epochs(model,epochs=5,callback=None):
    optimizer_local = tf.keras.optimizers.Adam()
    accuracy = tf.keras.metrics.SparseCategoricalAccuracy()
    if callback is not None:
        callback.set_model(model)
        callback.on_train_begin()
    for epoch in range(epochs):
        accuracy.reset_state()
        mean_loss = tf.keras.metrics.Mean()
        for batch_x,batch_y in loop_data:
            with tf.GradientTape() as tape:
                logits = model(batch_x,training=True)
                loss = loop_loss(batch_y,logits)
            gradients = tape.gradient(loss,model.trainable_variables)
            optimizer_local.apply_gradients(zip(gradients,model.trainable_variables))
            accuracy.update_state(batch_y,logits)
            mean_loss.update_state(loss)
        logs = {'loss':float(mean_loss.result()),'accuracy':float(accuracy.result())}
        print(epoch+1,logs)
        if callback is not None:callback.on_epoch_end(epoch,logs)
    if callback is not None:callback.on_train_end()
